// HasUsers filters parents that have a matching Users (a
// many-to-many relationship) using a correlated EXISTS subquery instead of
// INNER JOINs, so the parent rows are not multiplied. The optional filters are
// applied to the subquery (i.e. to Users).
func (w userWhereR[Q]) HasUsers(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	// self-referential: alias the subquery copy of the parent table so the
	// first-side correlation below still references the outer (parent) row.
	rel1 := Users.Columns.AliasedAs("Users1")
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Followers.NameExpr()),
		sm.InnerJoin(Users.NameExpr().As("Users1")).On(
			rel1.ID.EQ(Followers.Columns.FollowerID),
		),
		sm.Where(Followers.Columns.FolloweeID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// NULL-tolerant scan buffer for userScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type userPreloadBuf struct {
	ID             null.Val[uuid.UUID]
	CreatedAt      null.Val[time.Time]
	AuthID         null.Val[uuid.UUID]
	WeightUnit     null.Val[string]
	DistanceUnit   null.Val[string]
	Name           null.Val[string]
	FullNameSearch null.Val[string]
	Username       null.Val[string]
	AutofillSets   null.Val[bool]
	FeedSeenAt     null.Val[time.Time]
}

// userScanMapperNullable maps the preloaded user
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func userScanMapperNullable(prefix string) scan.Mapper[*User] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*User, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *userPreloadBuf) any
		}
		targets := make([]target, 0, 10)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.ID }})
			case "created_at":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.CreatedAt }})
			case "auth_id":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.AuthID }})
			case "weight_unit":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.WeightUnit }})
			case "distance_unit":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.DistanceUnit }})
			case "name":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.Name }})
			case "full_name_search":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.FullNameSearch }})
			case "username":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.Username }})
			case "autofill_sets":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.AutofillSets }})
			case "feed_seen_at":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.FeedSeenAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(userPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*User, error) {
				buf := link.(*userPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.AuthID.IsValue()) &&
					!(buf.WeightUnit.IsValue()) &&
					!(buf.DistanceUnit.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.FullNameSearch.IsValue()) &&
					!(buf.Username.IsValue()) &&
					!(buf.AutofillSets.IsValue()) &&
					!(buf.FeedSeenAt.IsValue()) {
					return nil, nil
				}

				o := new(User)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.AuthID.IsValue() {
					o.AuthID = buf.AuthID.MustGet()
				}
				if buf.WeightUnit.IsValue() {
					o.WeightUnit = buf.WeightUnit.MustGet()
				}
				if buf.DistanceUnit.IsValue() {
					o.DistanceUnit = buf.DistanceUnit.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.FullNameSearch.IsValue() {
					o.FullNameSearch = buf.FullNameSearch.MustGet()
				}
				if buf.Username.IsValue() {
					o.Username = buf.Username.MustGet()
				}
				if buf.AutofillSets.IsValue() {
					o.AutofillSets = buf.AutofillSets.MustGet()
				}
				o.FeedSeenAt = buf.FeedSeenAt
				return o, nil
			}
	}
}

func (o *User) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Exercises":
		rels, ok := retrieved.(ExerciseSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Exercises = rels
		o.R.Loaded.Exercises = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Users":
		rels, ok := retrieved.(UserSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Users = rels
		o.R.Loaded.Users = true

		return nil
	case "Notifications":
		rels, ok := retrieved.(NotificationSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Notifications = rels
		o.R.Loaded.Notifications = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Plans":
		rels, ok := retrieved.(PlanSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Plans = rels
		o.R.Loaded.Plans = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Routines":
		rels, ok := retrieved.(RoutineSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Routines = rels
		o.R.Loaded.Routines = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Sets":
		rels, ok := retrieved.(SetSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Sets = rels
		o.R.Loaded.Sets = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Auth":
		rel, ok := retrieved.(*Auth)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Auth = rel
		o.R.Loaded.Auth = true

		if rel != nil {
			rel.R.User = o
			rel.R.Loaded.User = true
		}
		return nil
	case "WorkoutComments":
		rels, ok := retrieved.(WorkoutCommentSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.WorkoutComments = rels
		o.R.Loaded.WorkoutComments = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	case "Workouts":
		rels, ok := retrieved.(WorkoutSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Workouts = rels
		o.R.Loaded.Workouts = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	default:
		return fmt.Errorf("user has no relationship %q", name)
	}
}

type userPreloader struct {
	Auth func(...psql.PreloadOption) psql.Preloader
}

func buildUserPreloader() userPreloader {
	return userPreloader{
		Auth: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Auth, AuthSlice](psql.PreloadRel{
				Name: "Auth",
				Sides: []psql.PreloadSide{
					{
						From:        Users,
						To:          Auths,
						FromColumns: []string{"auth_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Auths.Columns.Names(), authScanMapperNullable, opts...)
		},
	}
}

