// LoadExercises loads the user's Exercises into the .R struct
func (o *User) LoadExercises(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Exercises = nil
	o.R.Loaded.Exercises = false

	related, err := o.Exercises(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.User = o
		rel.R.Loaded.User = true
	}

	o.R.Exercises = related
	o.R.Loaded.Exercises = true
	return nil
}

// LoadExercises loads the user's Exercises into the .R struct
func (os UserSlice) LoadExercises(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	exercises, err := os.Exercises(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Exercises = nil
		o.R.Loaded.Exercises = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	userByKey := make(map[uuid.UUID][]*User, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		userByKey[o.ID] = append(userByKey[o.ID], o)
	}

	for _, rel := range exercises {

		owners, ok := userByKey[rel.UserID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.User = o
			rel.R.Loaded.User = true

			o.R.Exercises = append(o.R.Exercises, rel)

		}
	}

	return nil
}

// LoadUsers loads the user's Users into the .R struct
func (o *User) LoadUsers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Users = nil
	o.R.Loaded.Users = false

	related, err := o.Users(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	o.R.Users = related
	o.R.Loaded.Users = true
	return nil
}

// LoadUsers loads the user's Users into the .R struct
func (os UserSlice) LoadUsers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	q := os.Users(append(
		mods,
		// since we are changing the columns, the defaults must be added if the
		// original mods did not set any; this runs after the user mods and
		// before the related_* columns below, so it sees exactly what they set
		bob.ModFunc[*dialect.SelectQuery](func(q *dialect.SelectQuery) {
			if len(q.SelectList.Columns) == 0 {
				sm.Columns(Users.Columns).Apply(q)
			}
		}),
		sm.Columns(Followers.Columns.FolloweeID.As("related_users.ID")),
	)...)

	IDSlice := make([]uuid.UUID, 0, len(os))

	mapper := scan.Mod(q.Scanner, func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any, any) error) {
		// Resolve each joined key column name to its index once per query. The
		// previous code scanned by name on every row, which meant a linear column
		// search per row; the columns are added by this loader so they are always
		// present, but an unselected column simply stays unresolved and is skipped.
		IDIdx := -1
		for i, col := range cols {
			switch col {
			case "related_users.ID":
				IDIdx = i
			}
		}

		return func(row *scan.Row) (any, error) {
				IDSlice = append(IDSlice, *new(uuid.UUID))
				if IDIdx >= 0 {
					row.ScheduleScanByIndex(IDIdx, &IDSlice[len(IDSlice)-1])
				}

				return nil, nil
			},
			func(any, any) error {
				return nil
			}
	})

	users, err := bob.Allx[bob.SliceTransformer[*User, UserSlice]](ctx, exec, q, mapper)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}
		o.R.Users = nil
		o.R.Loaded.Users = true
	}
	// O(N+M) stitch via a map; child key is the carried slice IDSlice[i] (was O(N*M)).
	userByKey := make(map[uuid.UUID][]*User, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		userByKey[o.ID] = append(userByKey[o.ID], o)
	}

	for i, rel := range users {
		owners, ok := userByKey[IDSlice[i]]
		if !ok {
			continue
		}

		for _, o := range owners {
			o.R.Users = append(o.R.Users, rel)
		}
	}

	return nil
}

