// LoadAuth loads the user's Auth into the .R struct
func (os UserSlice) LoadAuth(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	auths, err := os.Auth(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Auth = nil
		o.R.Loaded.Auth = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	userByKey := make(map[uuid.UUID][]*User, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		userByKey[o.AuthID] = append(userByKey[o.AuthID], o)
	}

	for _, rel := range auths {

		owners, ok := userByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Auth != nil {
				continue
			}

			rel.R.User = o
			rel.R.Loaded.User = true

			o.R.Auth = rel

		}
	}

	return nil
}

